const parseYmdUtc = (value) => {
  const [y, m, d] = String(value || '').split('-').map(Number);
  return new Date(Date.UTC(y, (m || 1) - 1, d || 1));
};
const ymdUtc = (value) => value.toISOString().slice(0, 10);
const formatDateMx = (value) => {
  if (!value) return 'Sin datos';
